# deb dependencies of the host libraries: "<soname> <dependency>", read by resolve-deps.sh; a missing soname fails.
# The alternatives cover the t64 renames of Ubuntu 24.04 and Debian 13; plain names are Ubuntu 22.04's and Debian 12's.
ld-linux-x86-64.so.2 @glibc
libc.so.6 @glibc
libm.so.6 @glibc
libmvec.so.1 @glibc
libdl.so.2 @glibc
libpthread.so.0 @glibc
librt.so.1 @glibc
libresolv.so.2 @glibc
# GLIBCXX_3.4.29 (the Qt SDK's and the floor's ceiling) is GCC 11's.
libstdc++.so.6 libstdc++6 (>= 11)
libgcc_s.so.1 libgcc-s1
libEGL.so.1 libegl1
libGL.so.1 libgl1
libOpenGL.so.0 libopengl0
libGLX.so.0 libglx0
libgbm.so.1 libgbm1
libdrm.so.2 libdrm2
libX11.so.6 libx11-6
libX11-xcb.so.1 libx11-xcb1
libXext.so.6 libxext6
libXrandr.so.2 libxrandr2
libxcb.so.1 libxcb1
libxcb-cursor.so.0 libxcb-cursor0
libxcb-glx.so.0 libxcb-glx0
libxcb-icccm.so.4 libxcb-icccm4
